do $d$ declare s text; n text; begin s := pg_get_functiondef('public.report_balances_owed'::regproc); n := replace(s, 'select jsonb_build_object(''generated_at'', now(), ''rows'',', 'select jsonb_build_object(''generated_at'', now(), ''client_credited_total'', (select coalesce(sum(client_credited), 0) from x), ''rows'','); if n = s then raise exception 'no match'; end if; execute n; end $d$;;
